import static thaumcraft.test.ThaumaturgyProbe.*;
@Mod.EventBusSubscriber(modid=Thaumcraft.MODID)
public final class DartProbe {
 static final BlockPos Q=new BlockPos(900,205,8);static final UUID OWNER=UUID.fromString("7b23f12a-292f-4569-8aa6-548df2b0cff9");static final GolemDesign DESIGN=new GolemDesign(3,4,4,1,1),OLD=new GolemDesign(3,4,3,3,2);static GolemDart launched;static ServerPlayer p;static int ticks;static boolean done;
 static GolemBuilder press(BlockPos q){var l=p.level();l.removeBlock(q,false);l.setBlockAndUpdate(q,GolemContent.BUILDER.get().defaultBlockState());p.setPos(Vec3.atCenterOf(q).add(0,1,0));return (GolemBuilder)l.getBlockEntity(q);}
 static void complete(GolemBuilder b){while(b.working())check(b.insert("machina",Direction.DOWN,false),"Paid dart job rejected Machina");check(!b.insert("machina",Direction.DOWN,false),"Dart press charged extra Machina");}
 static void write(){var l=p.level();for(var e:l.getEntitiesOfClass(net.minecraft.world.entity.LivingEntity.class,new AABB(Q).inflate(15)))e.discard();for(var q:BlockPos.betweenClosed(Q.offset(-8,-1,-3),Q.offset(10,-1,3)))l.setBlockAndUpdate(q,Blocks.STONE.defaultBlockState());var b=press(Q);var menu=new GolemBuilderMenu(124,p.getInventory(),b);for(int n=0;n<4;n++)check(menu.clickMenuButton(p,2),"Cannot select dart arms");check(menu.design().arms()==4,"Dart menu data wrong");b.draft=DESIGN;GolemProbe.giveComponents(p,DESIGN);var before=java.util.stream.IntStream.range(0,36).mapToObj(i->p.getInventory().getItem(i).copy()).toList();var state=thaumcraft.research.ResearchService.state(p);thaumcraft.research.KnowledgeStore.write(p,state.stage("GOLEMCOMBATADV",0));check(!b.start(p)&&java.util.stream.IntStream.range(0,36).allMatch(i->ItemStack.matches(before.get(i),p.getInventory().getItem(i))),"Missing dart research charged materials");thaumcraft.research.KnowledgeStore.write(p,state);check(b.start(p)&&p.getInventory().isEmpty()&&b.insert("machina",Direction.DOWN,false)&&!b.start(p)&&!b.edit(p,2),"Dart reservation/lock failed");var old=press(Q.west(4));old.draft=OLD;GolemProbe.giveComponents(p,OLD);check(old.start(p)&&old.insert("machina",Direction.DOWN,false),"Old arm payment changed");var s=GolemProbe.seal(p,SealKind.GUARD_ADVANCED,Q.east(4));var g=new WorkerGolem(GolemContent.GOLEM.get(),l);g.configure(p,DESIGN,Q.east(2),0);g.setCustomName(Component.literal("Persistent darter"));g.cargo.setItem(0,new ItemStack(Items.DIAMOND,9));g.setHealth(7);l.addFreshEntity(g);var target=BatRiftClient.mob(p,Vec3.atBottomCenterOf(Q.east(6)));check(GolemDart.fire(l,g,p,s,target),"Native dart launch failed");var dart=launched;check(dart!=null,"Dart join event missing");var out=TagValueOutput.createWithContext(ProblemReporter.DISCARDING,l.registryAccess());dart.saveWithoutId(out);var copy=new GolemDart(GolemContent.DART.get(),l);copy.load(TagValueInput.create(ProblemReporter.DISCARDING,l.registryAccess(),out.buildResult()));check(copy.targetId().equals(target.getUUID())&&copy.sealPos().equals(s.getBlockPos())&&copy.expires()==dart.expires()&&copy.pickup==net.minecraft.world.entity.projectile.arrow.AbstractArrow.Pickup.DISALLOWED,"Dart NBT lost bound target/seal/expiry/pickup");check(!dart.mayHit(target),"Offline owner's dart could hurt target");g.setMode(2);Thaumcraft.LOGGER.info("DART_WRITE_OK: original components, research/payment/lock, paid old/new jobs, bound projectile NBT and offline-owner protection");}
 @SubscribeEvent public static void joined(net.minecraftforge.event.entity.EntityJoinLevelEvent e){if(System.getProperty("thaumcraft.thaumaturgyProbe","").startsWith("dart-")&&e.getEntity() instanceof GolemDart d&&d.level() instanceof ServerLevel)launched=d;}
 @SubscribeEvent public static void start(ServerStartedEvent e){String mode=System.getProperty("thaumcraft.thaumaturgyProbe","");if(!mode.equals("dart-write")&&!mode.equals("dart-read"))return;var l=e.getServer().overworld();for(int x=55;x<=57;x++)for(int z=-1;z<=1;z++)l.setChunkForced(x,z,true);l.setChunkForced(42,0,true);p=new ServerPlayer(e.getServer(),l,new GameProfile(OWNER,"DartProbe"),ClientInformation.createDefault()){@Override public void sendSystemMessage(Component c,boolean o){}@Override public void sendOverlayMessage(Component c){}@Override protected ItemCooldowns createItemCooldowns(){return new ItemCooldowns();}};knowledge(p);}
 @SubscribeEvent public static void tick(TickEvent.ServerTickEvent.Post e){String mode=System.getProperty("thaumcraft.thaumaturgyProbe","");if(!mode.equals("dart-write")&&!mode.equals("dart-read")||done||++ticks<60)return;var l=p.level();if(mode.equals("dart-write"))write();else{var b=(GolemBuilder)l.getBlockEntity(Q);check(b.working()&&b.draft.equals(DESIGN)&&b.remaining()==DESIGN.cost()-1,"Dart paid job lost progress");complete(b);check(b.output.getItem(0).get(GolemContent.DESIGN.get()).equals(DESIGN),"Dart output lost design");var old=(GolemBuilder)l.getBlockEntity(Q.west(4));check(old.working()&&old.draft.equals(OLD)&&old.remaining()==OLD.cost()-1,"Old arm paid job changed");complete(old);check(old.output.getItem(0).get(GolemContent.DESIGN.get()).equals(OLD),"Old arms output changed");check(l.getEntitiesOfClass(WorkerGolem.class,new AABB(Q).inflate(12)).stream().anyMatch(g->g.design().equals(DESIGN)&&g.arms()==4&&g.cargo.getItem(0).getCount()==9&&g.getHealth()==7&&g.mode()==2),"Saved darter lost design/arms/cargo/health");check(l.getEntitiesOfClass(GolemDart.class,new AABB(Q).inflate(20)).isEmpty(),"Offline/paused worker dart survived restart");Thaumcraft.LOGGER.info("DART_RESTART_OK: old/new press jobs, darter state and invalid in-flight dart cleanup");}
 check(l.getEntitiesOfClass(WorkerGolem.class,new AABB(ScoutProbe.Q).inflate(12)).stream().anyMatch(g->g.design().equals(ScoutProbe.SMART)&&g.arms()==0&&g.head()==4&&g.workRadius()==48&&g.cargo.getItem(0).getCount()==21&&g.getHealth()==5),"Actual port.24 Scout changed");Thaumcraft.LOGGER.info("DART_PORT24_OK: actual Smart Scout retained old arms, radius, health and cargo");done=true;e.server().halt(false);}
}
